@import url('https://fonts.googleapis.com/css2?family=Amaranth:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Benfica DNA — águia red command, lisbon light, gold wing */
.theme-benfica {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.975 0.007 67.7);
  --surface-2: oklch(0.938 0.013 63.9);
  --fg: oklch(0.226 0 0);
  --fg-muted: oklch(0.550 0.016 46.1);
  --accent: oklch(0.513 0.211 29.2);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.663 0.120 80.3);
  --line: oklch(0.903 0.016 64.7);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Amaranth", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-benfica h1,
.theme-benfica h2,
.theme-benfica h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-benfica { --font-ui: var(--font-display); }
.theme-benfica h1, .theme-benfica h2 { text-transform: uppercase; }
.theme-benfica button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-benfica { border-top: 6px solid var(--accent); }
.theme-benfica h1 { color: var(--accent); font-weight: 700; }
.theme-benfica h2::after { content: ""; display: block; width: 4rem; height: 2px; background: var(--accent-2); margin-top: 0.5rem; }

/* depth */
.theme-benfica thead th { color: var(--accent); text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.78em; border-bottom: 2px solid var(--accent); background: var(--surface); }
.theme-benfica td { border-bottom: 1px solid var(--line); }
.theme-benfica tbody tr:hover { background: oklch(0.513 0.211 29.2 / 7%); }
.theme-benfica a { color: var(--accent); text-underline-offset: 3px; text-decoration-color: oklch(0.663 0.120 80.3 / 60%); }
/* the eagle's wing: gold sweep under hovered links */
.theme-benfica a:hover { text-decoration-color: var(--accent-2); text-decoration-thickness: 2px; }
.theme-benfica ::selection { background: var(--accent); color: oklch(1 0 0); }
.theme-benfica input:focus-visible, .theme-benfica select:focus-visible, .theme-benfica textarea:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.theme-benfica kbd { background: oklch(1 0 0); border: 1px solid var(--line); border-bottom: 3px solid var(--accent-2); border-radius: var(--radius-sm); padding: 0.1em 0.45em; font-family: var(--font-mono); color: var(--accent); }
.theme-benfica ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-benfica ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-benfica ::-webkit-scrollbar-thumb { background: var(--accent); border-radius: 5px; border: 2px solid var(--surface-2); }
.theme-benfica ::-webkit-scrollbar-thumb:hover { background: oklch(0.60 0.13 80); }
.theme-benfica .label-caps { color: var(--accent); }
.theme-benfica .themed-border { border-color: var(--accent); border-bottom: 3px solid var(--accent-2); }
.theme-benfica button:hover { box-shadow: 0 4px 14px oklch(0.513 0.211 29.2 / 30%); }
.theme-benfica button:active { transform: translateY(1px); box-shadow: none; }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-benfica.alt-mode {
  --bg: oklch(0.188 0.012 40.0);
  --surface: oklch(0.228 0.014 42.0);
  --surface-2: oklch(0.272 0.016 44.0);
  --fg: oklch(0.952 0.010 78.0);
  --fg-muted: oklch(0.690 0.025 62.0);
  --accent: oklch(0.610 0.210 29.2);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.760 0.130 82.0);
  --line: oklch(0.76 0.05 70 / 22%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  background-image: radial-gradient(circle at 20% 30%, oklch(0.76 0.13 82 / 6%) 0 6px, transparent 6px), radial-gradient(circle at 70% 60%, oklch(0.76 0.13 82 / 5%) 0 5px, transparent 5px), radial-gradient(circle at 45% 85%, oklch(0.76 0.13 82 / 5%) 0 4px, transparent 4px);
  background-size: 240px 240px;
  border-top-color: var(--accent-2);
}
.theme-benfica.alt-mode h1 { color: var(--accent-2); }
.theme-benfica.alt-mode thead th { color: var(--accent-2); border-bottom-color: var(--accent-2); }
.theme-benfica.alt-mode a { color: var(--accent-2); text-decoration-color: oklch(0.61 0.21 29.2 / 60%); }
.theme-benfica.alt-mode a:hover { text-decoration-color: var(--accent); }
.theme-benfica.alt-mode kbd { background: var(--surface-2); border-color: var(--line); border-bottom-color: var(--accent-2); color: var(--accent-2); }
.theme-benfica.alt-mode input, .theme-benfica.alt-mode select, .theme-benfica.alt-mode textarea { background: oklch(0.165 0.010 40); border-color: var(--line); color: var(--fg); }
.theme-benfica.alt-mode .label-caps { color: var(--accent-2); }
.theme-benfica.alt-mode tbody tr:hover { background: oklch(0.76 0.13 82 / 8%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
